# FLUX 3 reference-image preprocessing against diffusers
# Flux3ImageProcessor (fixture generated by
# tools/gen_fixtures_flux3_preprocess.py, checked in).

if (!requireNamespace("torch", quietly = TRUE) || !torch::torch_is_installed()) {
  exit_file("torch not fully installed")
}
if (!requireNamespace("safetensors", quietly = TRUE)) {
  exit_file("safetensors not installed")
}

library(diffuseR)

fixture_path <- system.file("tinytest", "fixtures",
  "flux3_preprocess.safetensors", package = "diffuseR")
if (fixture_path == "") fixture_path <- "fixtures/flux3_preprocess.safetensors"
if (!file.exists(fixture_path)) exit_file("flux3 preprocess fixtures missing")

fx <- safetensors::safe_load_file(fixture_path, framework = "torch")

max_abs_diff <- function(a, b) {
  as.numeric(torch::torch_max(torch::torch_abs(
    a$to(dtype = torch::torch_float32()) - b$to(dtype = torch::torch_float32())
  )))
}

# a: 100x70 -> 112x80 canvas (reflect); b: 20x12 -> 64x64 canvas
# (symmetric, side <= 16, pad wider than the image); c: already on grid
for (name in c("a", "b", "c")) {
  arr <- as.array(fx[[paste0(name, "_input")]]$to(dtype = torch::torch_float64())) / 255
  res <- flux3_preprocess_image(arr)
  ref <- fx[[paste0(name, "_output")]]
  expect_equal(as.integer(res$image$shape), as.integer(ref$shape),
    info = name)
  expect_true(max_abs_diff(res$image, ref) < 1e-6, info = name)
  expect_equal(unname(res$crop),
    as.numeric(as.array(fx[[paste0(name, "_crop")]])), info = name)
}

# Downscale path: the canvas fits the cap (here 64x64 = 4096 px area)
arr <- array(runif(300 * 200 * 3), dim = c(200L, 300L, 3L))
res <- flux3_preprocess_image(arr, max_area = 96 * 64)
expect_true(prod(res$image$shape[3:4]) <= 96 * 64)
expect_equal(res$image$shape[3] %% 16, 0)
expect_equal(res$image$shape[4] %% 16, 0)
crop <- res$crop
expect_true(crop[["right"]] - crop[["left"]] <= res$image$shape[4])

# numpy.pad index maps
expect_equal(diffuseR:::.flux3_pad_index(4, 2, 2, "reflect"),
  c(3L, 2L, 1L, 2L, 3L, 4L, 3L, 2L))
expect_equal(diffuseR:::.flux3_pad_index(3, 4, 0, "symmetric"),
  c(3L, 3L, 2L, 1L, 1L, 2L, 3L))
